package com.hms.appointments;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import com.hms.doctors.*; import com.hms.tenancy.*; import java.util.*; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.http.MediaType; import org.springframework.test.context.ActiveProfiles; import org.springframework.test.web.servlet.MockMvc;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") class PatientControllerTests {@Autowired MockMvc mockMvc;@Autowired TenantRepository tenants;@Autowired PatientRepository patients;@BeforeEach void setup(){patients.deleteAll();tenants.deleteAll();tenants.save(new Tenant(UUID.randomUUID(),"patient-care","Patient Care",null,TenantStatus.ACTIVE,null,null));} @Test void rejectsPatientFromAnotherTenant() throws Exception {mockMvc.perform(get("/api/hospitals/patient-care/patients/00000000-0000-0000-0000-000000000001")).andExpect(status().isBadRequest());} @Test void searchesEmptyPatientDirectory() throws Exception {mockMvc.perform(get("/api/hospitals/patient-care/patients").param("query","unknown")).andExpect(status().isOk()).andExpect(jsonPath("$").isEmpty());}}
